import fs from "node:fs";
import path from "node:path";

const SVG_DIR = path.resolve("src/assets/fa");
const OUTPUT_FILE = path.resolve("src/types/fontawesome-icons.d.ts");

const files = fs.readdirSync(SVG_DIR)
    .filter(f => f.endsWith(".svg"))
    .map(f => `"${path.basename(f, ".svg")}"`);

const unionType = files.length > 0 ? files.join(" | ") : "never";

const content = `// Auto-generated by build/generate-svg-types.ts.
// Do not edit manually.

export type FontAwesomeSVGNames = ${unionType};
`;

fs.mkdirSync(path.dirname(OUTPUT_FILE), { recursive: true });
fs.writeFileSync(OUTPUT_FILE, content, "utf-8");

console.log(`Generated ${files.length} SVG icon types in ${OUTPUT_FILE}`);